CREATE SCHEMA IF NOT EXISTS support_qa;
CREATE TABLE IF NOT EXISTS support_qa.samples (sample_id BIGSERIAL PRIMARY KEY, ticket_id TEXT NOT NULL, sample_key TEXT NOT NULL UNIQUE, stratum TEXT NOT NULL, redacted_answer TEXT NOT NULL, knowledge_version TEXT NOT NULL, sampled_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_qa.evaluations (evaluation_id BIGSERIAL PRIMARY KEY, sample_id BIGINT NOT NULL UNIQUE REFERENCES support_qa.samples(sample_id), evaluator_version TEXT NOT NULL, grounding_score NUMERIC(5,4), confidence NUMERIC(5,4) NOT NULL, action TEXT NOT NULL CHECK(action IN ('pass','human_qa')), reasons JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_qa.knowledge_gaps (gap_id BIGSERIAL PRIMARY KEY, topic_key TEXT NOT NULL, knowledge_version TEXT NOT NULL, occurrence_count INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','drafting','published','dismissed')), UNIQUE(topic_key,knowledge_version));
CREATE TABLE IF NOT EXISTS support_qa.review_outcomes (evaluation_id BIGINT PRIMARY KEY REFERENCES support_qa.evaluations(evaluation_id), reviewer_id TEXT NOT NULL, label TEXT NOT NULL CHECK(label IN ('agree','disagree','uncertain')), reviewed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_support_qa_review ON support_qa.evaluations(action,created_at);
